mapper.select:
SELECT s.id, s.spot_name, sp.photo_url, r.average_rating, c.name AS category_name, sc.name AS sub_category_name, s.keywords FROM spots s LEFT JOIN sub_categories sc ON s.sub_category_id = sc.id LEFT JOIN categories c ON sc.category_id = c.id LEFT JOIN spot_photos sp ON s.id = sp.spot_id AND sp.display_order = 1 LEFT JOIN ( SELECT spot_id, AVG(rating) AS average_rating FROM reviews GROUP BY spot_id ) r ON r.spot_id = s.id
s.deleted_at IS NULL
AND (s.spot_name LIKE CONCAT('%', #{hira}, '%') OR s.keywords LIKE CONCAT('%', #{hira}, '%')
OR s.spot_name LIKE CONCAT('%', #{kana}, '%') OR s.keywords LIKE CONCAT('%', #{kana}, '%')
)
ORDER BY r.average_rating DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}
